public sealed class FrontlineMapMotionProbe:UnityEngine.MonoBehaviour {
 UnityEngine.RectTransform target;UnityEngine.Quaternion rotation;UnityEngine.Vector2 position;UnityEngine.Vector3 scale;string mode;float start;
 int lastFrame=-1;float lastAngle;bool observed;public float AngleTravel;public int RenderedFrames;public float MinAngle=360,MaxAngle=-360,MinScale=float.PositiveInfinity,MaxScale=float.NegativeInfinity;
 public void Begin(UnityEngine.RectTransform t,string m){target=t;mode=m;rotation=t.localRotation;position=t.anchoredPosition;scale=t.localScale;start=UnityEngine.Time.realtimeSinceStartup;UnityEngine.Canvas.willRenderCanvases+=Observe;}
 void Observe(){if(target==null)return;if(lastFrame!=UnityEngine.Time.frameCount){RenderedFrames++;lastFrame=UnityEngine.Time.frameCount;}float angle=target.localEulerAngles.z;if(observed)AngleTravel+=UnityEngine.Mathf.Abs(UnityEngine.Mathf.DeltaAngle(lastAngle,angle));lastAngle=angle;observed=true;MinAngle=UnityEngine.Mathf.Min(MinAngle,angle);MaxAngle=UnityEngine.Mathf.Max(MaxAngle,angle);MinScale=UnityEngine.Mathf.Min(MinScale,target.localScale.x);MaxScale=UnityEngine.Mathf.Max(MaxScale,target.localScale.x);}
 void Update(){if(target==null)return;float elapsed=UnityEngine.Time.realtimeSinceStartup-start;target.localRotation=rotation*UnityEngine.Quaternion.Euler(0,0,elapsed*45);target.anchoredPosition=position+new UnityEngine.Vector2(40*UnityEngine.Mathf.Sin(elapsed),30*UnityEngine.Mathf.Cos(elapsed));if(mode=="zoom")target.localScale=scale*(1+.25f*UnityEngine.Mathf.Sin(elapsed));}
 public void Restore(){UnityEngine.Canvas.willRenderCanvases-=Observe;if(target!=null){target.localRotation=rotation;target.anchoredPosition=position;target.localScale=scale;target=null;}}
}

